-- Add Abu Dhabi and Dubai as editable city presets and highlighted locations.
-- Rename the existing Taiwan label without replacing custom points, copy or statistics.
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE site_settings SET configuration=JSON_SET(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapCountries[*].id')),'.id','.label.zh'),CONVERT(0xe4b8ade59bbde58fb0e6b9be USING utf8mb4)) WHERE id='website' AND JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapCountries[*].id')) IS NOT NULL AND CAST(JSON_UNQUOTE(JSON_EXTRACT(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapCountries[*].id')),'.id','.label.zh'))) AS BINARY)=CAST(CONVERT(0xe58fb0e6b9be USING utf8mb4) AS BINARY) AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-22-global-map-locations-v1');
UPDATE site_settings SET configuration=JSON_SET(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapCountries[*].id')),'.id','.label.en'),CONVERT(0x54616977616e2c204368696e61 USING utf8mb4)) WHERE id='website' AND JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapCountries[*].id')) IS NOT NULL AND CAST(JSON_UNQUOTE(JSON_EXTRACT(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapCountries[*].id')),'.id','.label.en'))) AS BINARY)=CAST(CONVERT(0x54616977616e USING utf8mb4) AS BINARY) AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-22-global-map-locations-v1');
UPDATE site_settings SET configuration=JSON_ARRAY_APPEND(configuration,'$.mapCountries',CAST(CONVERT(0x7b226964223a22636974792d41452d6162752d6468616269222c22636f6465223a2241452d415a222c226c6162656c223a7b22656e223a22416275204468616269222c227a68223a22e998bfe5b883e6898ee6af94227d2c2278223a36342e3530312c2279223a34322e3430357d USING utf8mb4) AS JSON)) WHERE id='website' AND JSON_TYPE(JSON_EXTRACT(configuration,'$.mapCountries'))='ARRAY' AND JSON_SEARCH(configuration,'one',CONVERT(0x636974792d41452d6162752d6468616269 USING utf8mb4),NULL,'$.mapCountries[*].id') IS NULL AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-22-global-map-locations-v1');
UPDATE site_settings SET configuration=JSON_ARRAY_APPEND(configuration,'$.mapCountries',CAST(CONVERT(0x7b226964223a22636974792d41452d6475626169222c22636f6465223a2241452d4455222c226c6162656c223a7b22656e223a224475626169222c227a68223a22e8bfaae68b9c227d2c2278223a36342e3734342c2279223a34312e3839387d USING utf8mb4) AS JSON)) WHERE id='website' AND JSON_TYPE(JSON_EXTRACT(configuration,'$.mapCountries'))='ARRAY' AND JSON_SEARCH(configuration,'one',CONVERT(0x636974792d41452d6475626169 USING utf8mb4),NULL,'$.mapCountries[*].id') IS NULL AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-22-global-map-locations-v1');
UPDATE home_global_settings SET configuration=JSON_SET(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapPoints[*].id')),'.id','.label.zh'),CONVERT(0xe4b8ade59bbde58fb0e6b9be USING utf8mb4)) WHERE id=1 AND JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapPoints[*].id')) IS NOT NULL AND CAST(JSON_UNQUOTE(JSON_EXTRACT(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapPoints[*].id')),'.id','.label.zh'))) AS BINARY)=CAST(CONVERT(0xe58fb0e6b9be USING utf8mb4) AS BINARY) AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-22-global-map-locations-v1');
UPDATE home_global_settings SET configuration=JSON_SET(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapPoints[*].id')),'.id','.label.en'),CONVERT(0x54616977616e2c204368696e61 USING utf8mb4)) WHERE id=1 AND JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapPoints[*].id')) IS NOT NULL AND CAST(JSON_UNQUOTE(JSON_EXTRACT(configuration,REPLACE(JSON_UNQUOTE(JSON_SEARCH(configuration,'one','country-TW',NULL,'$.mapPoints[*].id')),'.id','.label.en'))) AS BINARY)=CAST(CONVERT(0x54616977616e USING utf8mb4) AS BINARY) AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-22-global-map-locations-v1');
UPDATE home_global_settings SET configuration=JSON_ARRAY_APPEND(configuration,'$.mapPoints',CAST(CONVERT(0x7b226964223a22636974792d41452d6162752d6468616269222c226c6162656c223a7b22656e223a22416275204468616269222c227a68223a22e998bfe5b883e6898ee6af94227d2c2278223a36342e3530312c2279223a34322e3430357d USING utf8mb4) AS JSON)) WHERE id=1 AND JSON_TYPE(JSON_EXTRACT(configuration,'$.mapPoints'))='ARRAY' AND JSON_SEARCH(configuration,'one',CONVERT(0x636974792d41452d6162752d6468616269 USING utf8mb4),NULL,'$.mapPoints[*].id') IS NULL AND JSON_LENGTH(JSON_EXTRACT(configuration,'$.mapPoints'))<100 AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-22-global-map-locations-v1');
UPDATE home_global_settings SET configuration=JSON_ARRAY_APPEND(configuration,'$.mapPoints',CAST(CONVERT(0x7b226964223a22636974792d41452d6475626169222c226c6162656c223a7b22656e223a224475626169222c227a68223a22e8bfaae68b9c227d2c2278223a36342e3734342c2279223a34312e3839387d USING utf8mb4) AS JSON)) WHERE id=1 AND JSON_TYPE(JSON_EXTRACT(configuration,'$.mapPoints'))='ARRAY' AND JSON_SEARCH(configuration,'one',CONVERT(0x636974792d41452d6475626169 USING utf8mb4),NULL,'$.mapPoints[*].id') IS NULL AND JSON_LENGTH(JSON_EXTRACT(configuration,'$.mapPoints'))<100 AND NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-22-global-map-locations-v1');
INSERT INTO app_migrations (id) SELECT '2026-10-22-global-map-locations-v1' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-22-global-map-locations-v1');
COMMIT;
